<script setup>
import {ref,reactive,computed,onMounted,watch} from 'vue';
import {ElConfigProvider,ElButton,ElInput,ElInputNumber,ElForm,ElFormItem,ElTable,ElTableColumn,ElTag,ElSelect,ElOption,ElPagination,ElTabs,ElTabPane,ElDialog,ElDrawer,ElEmpty,ElMessage,ElMessageBox} from 'element-plus';
import zhCn from 'element-plus/es/locale/lang/zh-cn';

const session=ref(null),csrf=ref(''),booting=ref(true),loginBusy=ref(false),loginError=ref('');
const loginForm=reactive({username:'admin',password:''}),view=ref('licenses');
const list=reactive({rows:[],total:0,page:1,pageSize:20,totals:{valid:0,devices:0,unbound:0,expiring:0}}),listBusy=ref(false),query=ref(''),status=ref('valid'),selected=ref([]),listError=ref('');
const issueVisible=ref(false),issueBusy=ref(false),issueError=ref(''),issueForm=reactive({label:'',count:1,days:30,devices:1,skinLimit:0}),issueRequest=ref('');
const resultVisible=ref(false),codes=ref([]),codesRevealed=ref(false),exportBusy=ref(false);
const detailVisible=ref(false),detailBusy=ref(false),detail=ref(null),detailError=ref(''),detailForm=reactive({label:'',devices:1,extendDays:0,skinLimit:0});
const releases=ref([]),releasesBusy=ref(false),passwordVisible=ref(false),passwordBusy=ref(false),passwordError=ref(''),passwordForm=reactive({oldPassword:'',newPassword:'',repeat:''});
const stateNames={unused:'待激活',active:'使用中',unbound:'待重新绑定',expired:'已到期',revoked:'已停用'};
const messages={AUTH_REQUIRED:'登录已失效，请重新登录。',LOGIN_FAILED:'账号或密码不正确。',LOGIN_RATE_LIMIT:'尝试次数较多，请稍后再试。',CSRF_FAILED:'页面会话已更新，请刷新后重试。',ORIGIN_FORBIDDEN:'请求来源校验失败，请使用当前管理入口。',INVALID_ISSUE_OPTIONS:'请检查生成数量、有效天数和设备数。',ISSUE_REQUEST_CONFLICT:'本次生成参数已变化，请重新打开生成窗口。',CODE_NOT_RETAINED:'旧版授权未保留完整激活码，请从原发码文件获取。',CODE_STORAGE_INVALID:'激活码存储校验失败，请检查授权备份。',LICENSE_CHANGED:'授权信息已变化，请刷新详情后再操作。',DEVICE_LIMIT_BELOW_BOUND:'设备数不能少于当前已经绑定的数量，请先解绑。',LICENSE_EXPIRED:'授权已到期，请先延长有效期。',PERMANENT_LICENSE_NO_EXTENSION:'永久授权无需延长期限。',DEVICE_NOT_FOUND:'设备绑定信息已变化，请刷新后重试。',OLD_PASSWORD_INVALID:'当前密码不正确。',PASSWORD_INVALID:'新密码需为 12～200 个字符。',PASSWORD_UNCHANGED:'新密码需要与当前密码不同。',AUTH_CHANGED:'管理会话已更新，请重新登录。',REQUEST_TOO_LARGE:'请求内容过大。',DOWNLOAD_RATE_LIMIT:'正在进行的下载较多，请稍后再试。'};
const apiUrl=route=>new URL('./api/'+route,location.href).href;
async function api(route,{method='GET',body,blob=false}={}){
  let response;try{response=await fetch(apiUrl(route),{method,credentials:'same-origin',cache:'no-store',headers:{...(body?{'content-type':'application/json'}:{}),...(method!=='GET'?{'x-csrf-token':csrf.value}:{})},...(body?{body:JSON.stringify(body)}:{})});}catch{throw new Error('NETWORK_UNAVAILABLE');}
  if(!response.ok){const value=await response.json().catch(()=>({}));throw new Error(value.error||(response.status===429?'LOGIN_RATE_LIMIT':'REQUEST_FAILED'));}
  return blob?response.blob():response.json();
}
const errorText=error=>messages[error.message]||(error.message==='NETWORK_UNAVAILABLE'?'暂时连接不到服务，请稍后重试。':'操作未完成，请稍后重试。');
async function refreshCsrf(){csrf.value=(await api('csrf')).csrf;}
function clearPrivateState(){codes.value=[];codesRevealed.value=false;detail.value=null;selected.value=[];resultVisible.value=false;detailVisible.value=false;issueVisible.value=false;passwordVisible.value=false;loginForm.password='';Object.assign(passwordForm,{oldPassword:'',newPassword:'',repeat:''});}
async function notify(error){if(error.message==='AUTH_REQUIRED'){clearPrivateState();session.value=null;await refreshCsrf().catch(()=>{});}ElMessage.error(errorText(error));}
async function login(){
  if(loginBusy.value)return;loginError.value='';if(!loginForm.username||!loginForm.password){loginError.value='请输入账号和密码。';return;}
  loginBusy.value=true;try{const value=await api('login',{method:'POST',body:loginForm});session.value=value;csrf.value=value.csrf;loginForm.password='';await loadList();}catch(error){loginError.value=errorText(error);if(error.message==='CSRF_FAILED')await refreshCsrf().catch(()=>{});}finally{loginBusy.value=false;}
}
async function logout(){try{await api('logout',{method:'POST',body:{}});clearPrivateState();session.value=null;await refreshCsrf();ElMessage.success('已退出管理后台。');}catch(error){await notify(error);}}
let listSequence=0,filterTimer;
async function loadList(){
  if(!session.value)return;const sequence=++listSequence;listBusy.value=true;listError.value='';selected.value=[];
  try{const value=await api('licenses?'+new URLSearchParams({q:query.value,status:status.value,page:String(list.page)}));if(sequence===listSequence)Object.assign(list,value);}catch(error){if(sequence===listSequence){listError.value=errorText(error);if(error.message==='AUTH_REQUIRED')await notify(error);}}finally{if(sequence===listSequence)listBusy.value=false;}
}
watch([query,status],()=>{clearTimeout(filterTimer);filterTimer=setTimeout(()=>{list.page=1;void loadList();},250);});
const formatTime=(value,full=true)=>{if(value===null)return '永久';const parts=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(value);const get=name=>parts.find(p=>p.type===name)?.value||'';return `${get('year')}/${get('month')}/${get('day')}`+(full?` ${get('hour')}:${get('minute')}`:'');};
const rowCode=row=>row.codeHint?'DSHC · •••• '+row.codeHint:'授权 · '+row.id.slice(-8);
const tagType=status=>({active:'success',expired:'info',revoked:'danger',unbound:'warning'}[status]||'primary');
function openIssue(){issueError.value='';issueRequest.value=crypto.randomUUID();issueVisible.value=true;}
function resetIssueRequest(){issueRequest.value=crypto.randomUUID();}
async function issue(){
  if(issueBusy.value)return;issueBusy.value=true;issueError.value='';
  try{const value=await api('licenses/issue',{method:'POST',body:{...issueForm,requestId:issueRequest.value}});codes.value=value.licenses;codesRevealed.value=false;issueVisible.value=false;resultVisible.value=true;await loadList();}catch(error){issueError.value=errorText(error);}finally{issueBusy.value=false;}
}
const displayedCodes=computed(()=>codes.value.map(row=>codesRevealed.value?row.code:'DSHC · •••• '+row.code.slice(-6)).join('\n'));
async function copyCodes(){try{await navigator.clipboard.writeText(codes.value.map(row=>row.code).join('\n'));ElMessage.success('完整激活码已复制。');}catch{codesRevealed.value=true;ElMessage.warning('浏览器未允许自动复制，请手动选中完整激活码。');}}
async function exportCodes(ids){
  if(exportBusy.value)return;exportBusy.value=true;
  try{const blob=await api('licenses/export',{method:'POST',body:{ids},blob:true});const href=URL.createObjectURL(blob),link=document.createElement('a');link.href=href;link.download='DSH激活码-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(href),1000);ElMessage.success('导出文件已准备下载。');}catch(error){await notify(error);}finally{exportBusy.value=false;}
}
async function openDetail(row){detailVisible.value=true;detail.value=null;detailError.value='';await loadDetail(row.id);}
async function loadDetail(id){try{detail.value=await api('licenses/'+id);Object.assign(detailForm,{label:detail.value.license.label,devices:detail.value.license.maxDevices,extendDays:0,skinLimit:detail.value.license.skinQuota?.limit??0});}catch(error){await notify(error);}}
async function saveDetail(){
  if(!detail.value||detailBusy.value)return;detailBusy.value=true;detailError.value='';
  try{const id=detail.value.license.id;await api('licenses/'+id+'/update',{method:'POST',body:{...detailForm,revision:detail.value.license.revision}});await loadDetail(id);await loadList();ElMessage.success('授权已更新。');}catch(error){detailError.value=errorText(error);}finally{detailBusy.value=false;}
}
async function confirmed(title,copy,action){try{await ElMessageBox.confirm(copy,title,{confirmButtonText:'确认',cancelButtonText:'取消',type:'warning',closeOnClickModal:false});await action();}catch(error){if(error!=='cancel'&&error!=='close')await notify(error);}}
function toggleLicense(){
  const row=detail.value.license,enable=row.status==='revoked';
  return confirmed(enable?'恢复这份授权？':'停用这份授权？',enable?'恢复后，用户可刷新授权并重新启动陪伴。':'用户下次联网校验时会停止陪伴。已有离线授权仍遵循其离线期限。',async()=>{await api('licenses/'+row.id+'/status',{method:'POST',body:{revision:row.revision,revoked:!enable}});await loadDetail(row.id);await loadList();ElMessage.success(enable?'授权已恢复。':'授权已停用。');});
}
function releaseDevice(deviceId,all=false){
  const row=detail.value.license;return confirmed(all?'解绑全部设备？':'解绑这台设备？','解绑会释放设备名额。该设备下次联网校验后停止陪伴，之后可用激活码重新绑定。',async()=>{await api('licenses/'+row.id+'/release-device',{method:'POST',body:{revision:row.revision,deviceId,all}});await loadDetail(row.id);await loadList();ElMessage.success('设备名额已释放。');});
}
async function revealCode(){try{const row=detail.value.license,value=await api('licenses/'+row.id+'/code',{method:'POST',body:{}});codes.value=[{...row,code:value.code}];codesRevealed.value=false;resultVisible.value=true;}catch(error){await notify(error);}}
const auditNames={issued:'生成授权',activated:'设备激活',deactivated:'用户解绑',revoked:'停用授权','console-license-enabled':'恢复授权','console-license-updated':'调整授权','console-device-released':'管理员解绑','console-code-viewed':'查看完整码','console-codes-exported':'导出激活码'};
const onlineInstallUrl=row=>row.installPath?new URL(row.installPath,location.origin).href:'';
async function copyInstallUrl(row){try{await navigator.clipboard.writeText(onlineInstallUrl(row));ElMessage.success('在线安装链接已复制。');}catch{ElMessage.warning('请选中链接手动复制。');}}
async function loadReleases(){releasesBusy.value=true;try{releases.value=(await api('releases')).rows;}catch(error){await notify(error);}finally{releasesBusy.value=false;}}
function openPassword(){Object.assign(passwordForm,{oldPassword:'',newPassword:'',repeat:''});passwordError.value='';passwordVisible.value=true;}
async function changePassword(){
  passwordError.value='';if(passwordForm.newPassword!==passwordForm.repeat){passwordError.value='两次输入的新密码不一致。';return;}if(passwordForm.newPassword.length<12){passwordError.value='新密码至少需要 12 个字符。';return;}
  passwordBusy.value=true;try{await api('password',{method:'POST',body:{oldPassword:passwordForm.oldPassword,newPassword:passwordForm.newPassword}});clearPrivateState();session.value=null;await refreshCsrf();ElMessage.success('密码已修改，请重新登录。');}catch(error){passwordError.value=errorText(error);}finally{passwordBusy.value=false;}
}
onMounted(async()=>{try{session.value=await api('session');csrf.value=session.value.csrf;await loadList();}catch(error){if(error.message!=='AUTH_REQUIRED')loginError.value=errorText(error);await refreshCsrf().catch(()=>{loginError.value='暂时连接不到管理服务。';});}finally{booting.value=false;}});
</script>

<template>
  <ElConfigProvider :locale="zhCn">
    <div v-if="booting" class="boot-state"><span class="brand-mark">D<span>·</span></span><p>正在连接管理服务…</p></div>
    <section v-else-if="!session" class="login-screen" data-screen-label="管理员登录">
      <div class="login-story"><a class="brand" href="./"><span class="brand-mark">D<span>·</span></span><span>DSH <b>主题盒子</b></span></a><div class="login-story-copy"><span class="eyebrow">PRIVATE DISTRIBUTION</span><h1>每一份陪伴，<br>由你来发放。</h1><p>激活码、设备绑定与安装包，一个入口管理。</p><div class="story-tags"><span>私有授权</span><span>设备管理</span><span>安装包分发</span></div></div><p class="story-foot">仅供管理员使用 · 用户请在 DSH 插件内激活</p></div>
      <div class="login-side"><ElForm class="login-card" label-position="top" @submit.prevent="login"><span class="eyebrow">管理控制台</span><h2>欢迎回来</h2><p class="muted login-description">登录后管理你的私有分发。</p><ElFormItem label="管理员账号"><ElInput v-model="loginForm.username" name="username" autocomplete="username" maxlength="40" /></ElFormItem><ElFormItem label="登录密码"><ElInput v-model="loginForm.password" name="password" type="password" autocomplete="current-password" maxlength="200" show-password placeholder="输入管理员密码" /></ElFormItem><p v-if="loginError" class="form-error" role="alert">{{ loginError }}</p><ElButton class="full" type="primary" native-type="submit" :loading="loginBusy">登录管理后台 <span class="login-arrow">→</span></ElButton><p class="login-foot">使用管理员凭据登录，管理密码与用户激活码分别保存。</p></ElForm></div>
    </section>
    <div v-else class="app-shell" data-screen-label="DSH 陪伴分发管理">
      <header class="topbar"><a class="brand" href="./"><span class="brand-mark">D<span>·</span></span><span>DSH <b>主题盒子</b></span></a><span class="header-divider"></span><span class="header-caption">分发管理</span><div class="account-actions"><span class="environment-tag">{{ session.environment==='preview'?'本地预览':'私有服务' }}</span><span class="account-avatar">A</span><span class="account-name">{{ session.username }}</span><ElButton link @click="openPassword">修改密码</ElButton><span class="header-divider small"></span><ElButton link @click="logout">退出</ElButton></div></header>
      <main><div class="page-heading"><div><span class="eyebrow">PRIVATE DISTRIBUTION</span><h1>分发管理</h1><p>把每一份授权，交到合适的人手里。</p></div><ElButton v-if="view==='licenses'" type="primary" @click="openIssue">＋ 生成激活码</ElButton><ElButton v-else @click="loadReleases">刷新版本</ElButton></div>
        <ElTabs v-model="view" class="main-tabs" @tab-change="name=>name==='releases'&&loadReleases()">
          <ElTabPane label="授权码" name="licenses">
            <div class="metrics"><div><span>有效授权</span><strong>{{ list.totals.valid }}</strong><small>当前可用的授权数量</small></div><div><span>绑定设备</span><strong>{{ list.totals.devices }}</strong><small>有效授权下的设备</small></div><div><span>7 天内到期</span><strong>{{ list.totals.expiring }}</strong><small>及时安排续期</small></div></div>
            <section class="list-panel"><div class="list-toolbar"><ElInput v-model="query" class="search-input" clearable placeholder="搜索备注、编号或码尾号" aria-label="搜索授权" maxlength="100" /><ElSelect v-model="status" class="status-select" aria-label="授权状态"><ElOption v-for="option in [{value:'valid',label:'有效授权'},{value:'all',label:'全部状态'},...Object.entries(stateNames).map(([value,label])=>({value,label}))]" :key="option.value" :value="option.value" :label="option.label" /></ElSelect><span class="toolbar-spacer"></span><ElButton :disabled="!selected.length" :loading="exportBusy" @click="exportCodes(selected.map(row=>row.id))">导出已选{{ selected.length?'（'+selected.length+'）':'' }}</ElButton><ElButton @click="loadList">刷新</ElButton></div><p v-if="listError" class="inline-error" role="alert">{{ listError }}</p>
              <ElTable v-loading="listBusy" :data="list.rows" row-key="id" @selection-change="value=>selected=value"><ElTableColumn type="selection" :selectable="row=>row.codeRecoverable" width="48" /><ElTableColumn label="授权 / 激活码" min-width="190"><template #default="{row}"><button class="identifier" @click="openDetail(row)">{{ rowCode(row) }}</button><span class="row-subtext">{{ formatTime(row.createdAt) }} 创建</span></template></ElTableColumn><ElTableColumn prop="label" label="备注 / 发放对象" min-width="170" show-overflow-tooltip /><ElTableColumn label="状态" width="120"><template #default="{row}"><ElTag :type="tagType(row.status)" effect="light" size="small">{{ stateNames[row.status] }}</ElTag></template></ElTableColumn><ElTableColumn label="设备" width="85"><template #default="{row}"><span class="device-fraction">{{ row.devices.length }} <i>/ {{ row.maxDevices }}</i></span></template></ElTableColumn><ElTableColumn label="皮肤" width="105"><template #default="{row}"><span>{{ row.skinQuota?.used??0 }} / {{ row.skinQuota?.limit||'不限量' }}</span></template></ElTableColumn><ElTableColumn label="到期时间 · 北京时间" min-width="155"><template #default="{row}"><span class="date-primary">{{ formatTime(row.expiresAt,false) }}</span><span v-if="!row.permanent" class="row-subtext">{{ formatTime(row.expiresAt).slice(-5) }}</span></template></ElTableColumn><ElTableColumn label="操作" width="80" fixed="right"><template #default="{row}"><ElButton link type="primary" @click="openDetail(row)">管理</ElButton></template></ElTableColumn><template #empty><ElEmpty :image-size="55" :description="query?'没有匹配的授权':'还没有授权码'" /></template></ElTable>
              <div class="list-footer"><span>完整激活码仅向管理员显示。</span><ElPagination v-model:current-page="list.page" :page-size="list.pageSize" :total="list.total" layout="total, prev, pager, next" small @current-change="loadList" /></div>
            </section><p class="page-footnote">启动动画与桌宠共用一份授权；停用或解绑将在客户端下次联网校验时生效。</p>
          </ElTabPane>
          <ElTabPane label="安装包" name="releases"><section v-loading="releasesBusy" class="release-list"><article v-for="(row,index) in releases" :key="row.id" class="release-card"><div class="release-main"><div><div class="release-title"><h2>{{ row.version }}</h2><ElTag :type="index===0?'primary':'info'" size="small">{{ index===0?'最新版本':'历史版本' }}</ElTag></div><p>{{ row.platform==='darwin-arm64'?'Mac · Apple 芯片':row.platform }} <span>·</span> {{ (row.size/1000000).toFixed(1) }} MB</p></div><a class="el-button el-button--primary is-plain" :href="apiUrl('releases/'+row.id+'/download')">下载到本机</a></div><div class="release-meta"><span>适配版本 <b>{{ row.supportedDsh.map(value=>'DSH '+value).join('、') }}</b></span><span>发布时间 <b>{{ formatTime(row.publishedAt) }}</b></span></div><p class="release-hash">SHA-256 <code>{{ row.sha256 }}</code></p><div v-if="row.publicInstall" class="online-install"><b>用户在线安装链接</b><div class="install-copy-row"><ElInput :model-value="onlineInstallUrl(row)" readonly aria-label="在线安装链接" /><ElButton @click="copyInstallUrl(row)">复制链接</ElButton></div><p>把链接填入 DSH「添加插件」的插件输入框，安装后在「陪伴」内输入激活码。</p></div></article><ElEmpty v-if="!releasesBusy&&!releases.length" description="暂时没有已发布的安装包" /></section><p class="page-footnote">先提供安装包，再发放激活码。用户在插件里激活，并获取后续更新。</p></ElTabPane>
        </ElTabs>
        <footer class="app-foot"><span>DSH 陪伴 · 私有分发</span><a href="./THIRD_PARTY_NOTICES.txt" target="_blank" rel="noopener">开源组件</a></footer>
      </main>
    </div>

    <ElDialog v-model="issueVisible" title="生成激活码" width="490px" class="admin-dialog" :close-on-click-modal="false" :close-on-press-escape="!issueBusy" :show-close="!issueBusy"><p class="dialog-intro">为本次分发设置备注与使用范围。</p><ElForm label-position="top" @submit.prevent="issue" @input="resetIssueRequest"><ElFormItem label="备注 / 发放对象"><ElInput v-model="issueForm.label" maxlength="80" placeholder="例如：朋友内测 · 第一批" :disabled="issueBusy" /></ElFormItem><div class="form-grid"><ElFormItem label="生成数量"><ElInputNumber v-model="issueForm.count" :min="1" :max="100" :disabled="issueBusy" /></ElFormItem><ElFormItem label="有效天数"><ElInputNumber v-model="issueForm.days" :min="0" :max="3650" :disabled="issueBusy" /></ElFormItem></div><ElFormItem label="每个激活码可绑定的设备数"><ElInputNumber v-model="issueForm.devices" :min="1" :max="50" :disabled="issueBusy" /></ElFormItem><ElFormItem label="可下载皮肤数量（0 代表不限量）"><ElInputNumber v-model="issueForm.skinLimit" :min="0" :max="100000" :precision="0" :disabled="issueBusy" /></ElFormItem><p class="field-hint">按不同皮肤累计计数，重装和更新不重复计数，卸载不返还名额。</p><p class="field-hint">0 天表示永久有效；其他天数从生成时开始计算。一次最多生成 100 个。</p><p v-if="issueError" class="form-error" role="alert">{{ issueError }}</p><div class="dialog-actions"><ElButton :disabled="issueBusy" @click="issueVisible=false">取消</ElButton><ElButton type="primary" native-type="submit" :loading="issueBusy">生成激活码</ElButton></div></ElForm></ElDialog>

    <ElDialog v-model="resultVisible" title="激活码已准备好" width="560px" class="admin-dialog" :close-on-click-modal="false" @closed="codes=[];codesRevealed=false"><p class="dialog-intro">共 {{ codes.length }} 个。以后也可从授权详情中重新查看和导出。</p><div class="code-label"><span>激活码</span><ElButton link type="primary" @click="codesRevealed=!codesRevealed">{{ codesRevealed?'隐藏完整激活码':'显示完整激活码' }}</ElButton></div><ElInput :model-value="displayedCodes" type="textarea" :rows="6" readonly class="code-box" aria-label="本次激活码，默认隐藏" /><div class="dialog-actions result-actions"><ElButton @click="copyCodes">复制完整激活码</ElButton><ElButton type="primary" :loading="exportBusy" @click="exportCodes(codes.map(row=>row.id))">下载 CSV</ElButton><ElButton link @click="resultVisible=false">完成</ElButton></div></ElDialog>

    <ElDrawer v-model="detailVisible" title="授权详情" size="min(530px,100vw)" class="admin-drawer"><div v-if="detail"><div class="detail-identity"><div><ElTag :type="tagType(detail.license.status)" size="small">{{ stateNames[detail.license.status] }}</ElTag><code>{{ detail.license.id }}</code></div><ElButton size="small" :disabled="!detail.license.codeRecoverable" @click="revealCode">查看激活码</ElButton></div><p v-if="!detail.license.codeRecoverable" class="field-hint legacy-note">此授权创建于管理页上线前，完整码请从原发码文件获取。</p><ElForm label-position="top" @submit.prevent="saveDetail"><ElFormItem label="备注 / 发放对象"><ElInput v-model="detailForm.label" maxlength="80" /></ElFormItem><div class="detail-time"><span>到期时间</span><b>{{ formatTime(detail.license.expiresAt) }}</b></div><div class="form-grid"><ElFormItem label="延长有效期（天）"><ElInputNumber v-model="detailForm.extendDays" :min="0" :max="3650" :disabled="detail.license.permanent" /></ElFormItem><ElFormItem label="设备数量上限"><ElInputNumber v-model="detailForm.devices" :min="1" :max="50" /></ElFormItem></div><ElFormItem label="可下载皮肤数量（0 代表不限量）"><ElInputNumber v-model="detailForm.skinLimit" :min="0" :max="100000" :precision="0" /></ElFormItem><p class="field-hint">已领取 {{ detail.license.skinQuota?.used??0 }} 套，卸载不返还名额。调整上限会保留已领取的皮肤。</p><p class="field-hint">{{ detail.license.permanent?'永久授权无需延长期限，可继续调整设备数量。':'未到期从原到期时间顺延；已到期从现在起计算。' }}</p><p v-if="detailError" class="form-error">{{ detailError }}</p><ElButton type="primary" class="full" native-type="submit" :loading="detailBusy">保存调整</ElButton></ElForm><section class="detail-section"><div class="section-heading"><h3>绑定设备 <span>{{ detail.license.devices.length }} / {{ detail.license.maxDevices }}</span></h3><ElButton link type="danger" :disabled="!detail.license.devices.length" @click="releaseDevice(undefined,true)">解绑全部</ElButton></div><article v-for="device in detail.license.devices" :key="device.id" class="device-item"><div><strong>{{ device.id.slice(0,10) }}…{{ device.id.slice(-6) }}</strong><p>{{ formatTime(device.boundAt) }} 绑定</p></div><ElButton link type="danger" @click="releaseDevice(device.id)">解绑</ElButton></article><p v-if="!detail.license.devices.length" class="device-empty">当前没有绑定设备</p></section><section class="detail-section"><h3>最近操作</h3><ol class="audit-list"><li v-for="(item,index) in detail.audit" :key="index"><span>{{ auditNames[item.type]||'授权更新' }}</span><time>{{ formatTime(item.at).slice(5) }}</time></li></ol></section><div class="detail-bottom"><p>停用在下次联网校验时生效；已有离线授权仍遵循其离线期限。</p><ElButton :type="detail.license.status==='revoked'?'primary':'danger'" plain @click="toggleLicense">{{ detail.license.status==='revoked'?'恢复授权':'停用授权' }}</ElButton></div></div><div v-else class="muted">正在读取授权…</div></ElDrawer>

    <ElDialog v-model="passwordVisible" title="修改登录密码" width="450px" class="admin-dialog" :close-on-click-modal="false"><p class="dialog-intro">修改后，所有管理会话都会退出。</p><ElForm label-position="top" @submit.prevent="changePassword"><ElFormItem label="当前密码"><ElInput v-model="passwordForm.oldPassword" type="password" autocomplete="current-password" /></ElFormItem><ElFormItem label="新密码"><ElInput v-model="passwordForm.newPassword" type="password" autocomplete="new-password" maxlength="200" placeholder="至少 12 个字符" /></ElFormItem><ElFormItem label="再次输入新密码"><ElInput v-model="passwordForm.repeat" type="password" autocomplete="new-password" maxlength="200" /></ElFormItem><p v-if="passwordError" class="form-error">{{ passwordError }}</p><div class="dialog-actions"><ElButton @click="passwordVisible=false">取消</ElButton><ElButton type="primary" native-type="submit" :loading="passwordBusy">保存新密码</ElButton></div></ElForm></ElDialog>
  </ElConfigProvider>
</template>
